program_code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            rr, cc = 31-r, 31-c
            if 0 <= rr < h and grid[rr][c] != 6:
                out[r][c] = grid[rr][c]
            elif 0 <= cc < w and grid[r][cc] != 6:
                out[r][c] = grid[r][cc]
            else:
                # Recover the hidden central mirror pair from the nearest visible cells.
                vals = []
                for direction in (-1, 1):
                    nc = c + direction
                    while 0 <= nc < w and grid[r][nc] == 6:
                        nc += direction
                    if 0 <= nc < w:
                        vals.append(grid[r][nc])
                out[r][c] = max(set(vals), key=vals.count) if vals else 0
    return out
'''
program_path.write_text(program_code)
spec=importlib.util.spec_from_file_location('task_prog', program_path)
mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
out=mod.transform(test_grid)
print('\n'.join(' '.join(map(str,row)) for row in out))
print('remaining',sum(v==6 for row in out for v in row),'zeros',sum(v==0 for row in out for v in row))
